<script setup>
import { computed } from 'vue';
import { year } from '../state/year.js';
import { getTerm } from '../data/terms.js';
import { DEMO_TERMS, FARM_TASKS, PROVERBS, relationsFor } from '../data/linkedRecords.js';
defineProps({compact:Boolean});
const displayTerm=computed(()=>year.state.focus?getTerm(year.state.relatedTermIds[0]):year.term.value);
const relations=computed(()=>year.state.focus?relationsFor(year.state.focus.kind,year.state.focus.id):null);
const records=computed(()=>({tasks:FARM_TASKS.filter(item=>item.termId===displayTerm.value.id),proverbs:PROVERBS.filter(item=>item.termIds[0]===displayTerm.value.id)}));
function focus(kind,item) {
  const relation=relationsFor(kind,item.id);
  year.setFocus({kind,id:item.id},relation.termIds);
  year.selectTerm(relation.termIds[0],{clear:false}); year.setPanel(true);
}
function isRelated(kind,id) { return !relations.value||relations.value[kind==='task'?'taskIds':'proverbIds'].includes(id); }
</script>
<template>
  <section class="linked-records" :class="{'is-compact':compact}" aria-label="农谚农事交叉联动" @click.self="year.clearFocus">
    <div class="records-heading"><div><p class="eyebrow">农谚 × 农事</p><h2>一句农谚，连起一季农忙。</h2></div><button v-if="year.state.focus" class="text-link" @click="year.clearFocus">清除关联 ×</button><span v-else class="records-demo-badge">关系演示</span></div>
    <p class="records-note">下列文案与关联均为示例，待用核验资料替换。点击农谚或农事，可看转盘、节气轴与关联条目一起变化。</p>
    <div class="records-term-choices" aria-label="查看示例节气"><button v-for="id in DEMO_TERMS" :key="id" :class="{active:displayTerm.id===id}" @click="year.selectTerm(id)">{{getTerm(id).name}}</button></div>
    <details class="proverb-index"><summary>随谚寻时 · 浏览全部示例农谚</summary><div><button v-for="item in PROVERBS" :key="item.id" @click="focus('proverb',item)"><small>{{getTerm(item.termIds[0]).name}} · {{item.region==='north'?'北方':'南方'}} · 示例</small><span>{{item.text}}</span></button></div></details>
    <Transition name="record-fade" mode="out-in"><div :key="displayTerm.id" class="records-content"><div v-if="!records.tasks.length" class="records-empty">{{displayTerm.name}}的农事与谚语尚未录入，可先选上面的节气体验联动。</div><div v-else class="records-columns"><div v-for="region in ['north','south']" :key="region" class="records-column"><h3><i :class="region"></i>{{region==='north'?'北方':'南方'}} · {{displayTerm.name}}</h3><span class="records-subtitle">农事</span><button v-for="item in records.tasks.filter(item=>item.region===region)" :key="item.id" class="record-card" :class="{'is-related':relations&&isRelated('task',item.id),'is-dimmed':!isRelated('task',item.id),'is-focused':year.state.focus?.id===item.id}" :aria-pressed="year.state.focus?.id===item.id" @click="focus('task',item)"><small>示例</small><p>{{item.text}}</p><span>出处：{{item.source}}</span></button><span class="records-subtitle">农谚</span><button v-for="item in records.proverbs.filter(item=>item.region===region)" :key="item.id" class="record-card proverb-card" :class="{'is-related':relations&&isRelated('proverb',item.id),'is-dimmed':!isRelated('proverb',item.id),'is-focused':year.state.focus?.id===item.id}" :aria-pressed="year.state.focus?.id===item.id" @click="focus('proverb',item)"><small>示例</small><p>{{item.text}}</p><span>出处：{{item.source}} · {{item.termIds.map(id=>getTerm(id).name).join(' / ')}}</span></button></div></div></div></Transition>
    <p v-if="relations" class="relation-hint" role="status">已关联 {{relations.termIds.map(id=>getTerm(id).name).join('、')}} · {{relations.taskIds.length}}条农事 · {{relations.proverbIds.length}}条农谚 <span>按 Esc 清除</span></p>
  </section>
</template>
<style scoped>
.linked-records{margin:28px 0;padding:24px;background:#faf8efcc;border:1px solid #c9cebca8}.records-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.records-heading h2{font-size:22px}.records-heading .eyebrow{font-size:10px;margin-bottom:4px}.records-demo-badge{font-size:10px;border:1px solid #baa887;color:#927a52;padding:3px 8px;white-space:nowrap}.records-note{font-size:11px;color:#78816f;margin:12px 0 16px;line-height:1.9}.records-term-choices{display:flex;gap:8px;margin-bottom:20px}.records-term-choices button{font-size:11px;padding:4px 16px;border:1px solid #d0d4c1}.records-term-choices button.active{background:#526d5b;color:#faf5e5;border-color:#526d5b}.records-columns{display:grid;grid-template-columns:1fr 1fr;gap:26px}.records-column h3{font-size:15px;display:flex;align-items:center;gap:8px;margin-bottom:15px}.records-column h3 i{width:4px;height:13px;background:#b5986d}.records-column h3 i.south{background:#83a18b}.records-subtitle{font-size:10px;letter-spacing:.15em;color:#8b917e;display:block;margin:12px 0 8px}.record-card{display:block;width:100%;text-align:left;border:1px solid #cbd0bf;border-radius:2px;background:#fffdf455;padding:12px;margin-top:8px;transition:opacity .18s,transform .18s}.record-card>small{font-size:8px;color:#a17c4c;border:1px solid #c8b99b;padding:0 4px}.record-card p{font-size:12px;margin:5px 0;color:#415b4a;line-height:1.9}.record-card>span{font-size:9px;color:#8b927e}.record-card:hover{transform:translateX(3px)}.record-card.is-related{border-color:#a16a4f;animation:related 1.2s ease-out}.record-card.is-focused{background:#eadbc23b}.record-card.is-dimmed{opacity:.45}.proverb-card{border-style:dashed}.records-empty{padding:28px;text-align:center;font-size:12px;color:#84917b;border:1px dashed #c7ceba}.relation-hint{font-size:11px;color:#9c684b;margin-top:18px}.relation-hint span{float:right;font-size:9px;color:#8b927e}.record-fade-enter-active,.record-fade-leave-active{transition:opacity .18s}.record-fade-enter-from,.record-fade-leave-to{opacity:0}.is-compact{padding:17px;margin:18px 0}.is-compact .records-heading h2{font-size:17px}.is-compact .records-note{font-size:10px}.is-compact .records-columns{gap:14px}.is-compact .record-card{padding:9px}.is-compact .record-card p{font-size:11px}.is-compact .records-term-choices button{padding:3px 10px}@keyframes related{0%,70%{box-shadow:0 0 0 3px #ad77502b}100%{box-shadow:0 0 0 0 transparent}}@media(max-width:700px){.records-columns{grid-template-columns:1fr}.records-heading h2{font-size:18px}.linked-records{padding:16px}}
.proverb-index{font-size:10px;color:#6c7f64;margin:0 0 18px;border-block:1px solid #d4dac780;padding:8px 0}.proverb-index summary{cursor:pointer}.proverb-index>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}.proverb-index button{text-align:left;padding:10px;border:1px solid #c7d0bb;background:#fffdf455}.proverb-index button small{display:block;color:#a67c51;font-size:9px;margin-bottom:5px}.proverb-index button span{font-size:11px}.is-compact .proverb-index>div{grid-template-columns:1fr}.is-compact .proverb-index button{padding:7px}
</style>
